DO $v3_stage_world_exit$
DECLARE
  digest text;
BEGIN
  IF (SELECT count(*) FROM public.game_content_spawns WHERE content_version = 'v3') <> 730 THEN
    RAISE EXCEPTION 'V3 spawn set is incomplete';
  END IF;
  IF (SELECT count(*) FROM public.game_world_nodes WHERE content_version = 'v3') <> 369 THEN
    RAISE EXCEPTION 'V3 node state is incomplete';
  END IF;
  IF (SELECT count(*) FROM public.game_world_monsters WHERE content_version = 'v3') <> 361 THEN
    RAISE EXCEPTION 'V3 monster state is incomplete';
  END IF;
  IF (SELECT count(*) FROM public.game_content_spawns WHERE content_version = 'v2') <> 730 THEN
    RAISE EXCEPTION 'V3 staging modified the v2 spawn set';
  END IF;

  SELECT md5(string_agg(
           spawn_id::text || ':' || entity_type || ':' || kind || ':' || ordinal || ':' || x::float8::text
             || ':' || y::float8::text || ':' || biome || ':' || subzone, ',' ORDER BY spawn_id::text))
    INTO digest FROM public.game_content_spawns WHERE content_version = 'v3';
  IF digest <> '8c6963545a5d7a3c337e51316fa09a08' THEN
    RAISE EXCEPTION 'V3 spawn rows do not match the released artifact (%)', digest;
  END IF;

  SELECT md5(string_agg(
           spawn_id::text || ':' || kind || ':' || cell || ':' || x::float8::text || ':' || y::float8::text
             || ':' || max_charges || ':' || gather_s::float8::text || ':' || respawn_s, ',' ORDER BY spawn_id::text))
    INTO digest FROM public.game_world_nodes WHERE content_version = 'v3';
  IF digest <> '9e30a2a1ac3633c6cb843a15f7559fbb' THEN
    RAISE EXCEPTION 'V3 node rows do not match the released artifact (%)', digest;
  END IF;

  SELECT md5(string_agg(
           spawn_id::text || ':' || kind || ':' || cell || ':' || x::float8::text || ':' || y::float8::text
             || ':' || max_hp || ':' || respawn_s, ',' ORDER BY spawn_id::text))
    INTO digest FROM public.game_world_monsters WHERE content_version = 'v3';
  IF digest <> 'f9a51a13c10411aeee948689ead37a6c' THEN
    RAISE EXCEPTION 'V3 monster rows do not match the released artifact (%)', digest;
  END IF;

  IF (SELECT active_content_version FROM public.game_content_control WHERE singleton) <> 'v2' THEN
    RAISE EXCEPTION 'V3 world staging changed the active release';
  END IF;
END
$v3_stage_world_exit$;

